-- DB2 temporal helpers (postgres-native). DB2 stores wall-clock timestamps
-- as TEXT in canonical UTC format 'YYYY-MM-DD HH24:MI:SS'. pg_now_text()
-- returns "now" in that format; the modifier overload returns "now + interval"
-- where the modifier is a postgres interval string ('+7 days', '-30 days',
-- '-1800 seconds', etc.). julianday() / datetime() sqlite-compat shims that
-- previously sat here have been retired — application SQL now emits native
-- pg_now_text() and EXTRACT(EPOCH FROM x::timestamp)/86400.0 directly.
CREATE OR REPLACE FUNCTION pg_now_text() RETURNS TEXT AS $$
  SELECT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS');
$$ LANGUAGE SQL STABLE;
CREATE OR REPLACE FUNCTION pg_now_text(modifier TEXT) RETURNS TEXT AS $$
  SELECT to_char((now() AT TIME ZONE 'UTC') + (modifier)::interval,
                 'YYYY-MM-DD HH24:MI:SS');
$$ LANGUAGE SQL STABLE;
CREATE TABLE IF NOT EXISTS rules (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  polarity TEXT NOT NULL,  title TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  weight BIGINT NOT NULL DEFAULT 5,  domain TEXT NOT NULL DEFAULT '',  directive_type TEXT NOT NULL DEFAULT 'soft',  expires_at TEXT DEFAULT NULL,  last_reinforced_at TEXT DEFAULT NULL,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS projects (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  name TEXT NOT NULL UNIQUE,  root TEXT NOT NULL,  workspace TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project_id BIGINT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,  path TEXT NOT NULL,  purpose TEXT NOT NULL DEFAULT '',  hash TEXT NOT NULL DEFAULT '',  scanned_at TEXT NOT NULL,  language TEXT NOT NULL DEFAULT '',  vendored INTEGER NOT NULL DEFAULT 0,  UNIQUE(project_id, path));
-- H0b (cross-repo precision §1.5/§4): per-file language tag + vendored/third-party flag, populated
-- at index time from the path (xrepo_lang_name / xrepo_path_is_vendored). Feeds the same-language
-- corroboration gate (§1b) and vendored canonical-preference (§4); '' / 0 = unknown until re-index.
ALTER TABLE files ADD COLUMN IF NOT EXISTS language TEXT NOT NULL DEFAULT '';
ALTER TABLE files ADD COLUMN IF NOT EXISTS vendored INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS file_exports (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS file_imports (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '',  is_system INTEGER NOT NULL DEFAULT 0);
-- H6: file_imports.is_system (1 = C/C++ angle `#include <...>`). pg17 live DB: ADD COLUMN IF NOT
-- EXISTS only; the sqlite shim/tests get it from the inline CREATE above.
ALTER TABLE file_imports ADD COLUMN IF NOT EXISTS is_system INTEGER NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS terms (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  name TEXT NOT NULL,  kind TEXT NOT NULL DEFAULT '',  def_kind TEXT NOT NULL DEFAULT '',  line BIGINT NOT NULL DEFAULT 0,  line_end BIGINT NOT NULL DEFAULT 0);
ALTER TABLE terms ADD COLUMN IF NOT EXISTS line_end BIGINT NOT NULL DEFAULT 0;
-- H0a (cross-repo precision): granular definition kind alongside the coarse kind
-- ('definition'/'route'). Separate column so the many kind='definition' consumers are untouched.
-- def_kind CONTRACT (pinned here; the cross-repo resolver applies it for §5 kind-eligibility):
--   ''                       legacy/migrated row or route -> UNKNOWN, treated as ELIGIBLE
--   'definition'             first-party def from a not-yet-granular (non-C) scanner -> ELIGIBLE
--   'function'               first-party API -> ELIGIBLE (HIGH-capable)
--   'struct'/'enum'/'union'  first-party type -> ELIGIBLE (HIGH-capable)
--   'macro'/'typedef'        SDK-prone (e.g. DEFINE_GUID/EGLDisplay) -> NOT HIGH-eligible (§5)
-- Default '' on existing rows is intentional (eligible) until H4 re-indexes the corpus. Postgres
-- ADD COLUMN IF NOT EXISTS only (pg17 live DB); the sqlite shim/tests get def_kind from the inline
-- CREATE above (no sqlite ALTER) — same pattern as line_end.
ALTER TABLE terms ADD COLUMN IF NOT EXISTS def_kind TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS stopwords (  word TEXT PRIMARY KEY);
CREATE TABLE IF NOT EXISTS entity_edges (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  source TEXT NOT NULL,  relation TEXT NOT NULL,  target TEXT NOT NULL,  weight BIGINT NOT NULL DEFAULT 1,  window_id BIGINT, utility_score DOUBLE PRECISION NOT NULL DEFAULT 0.0, valid_from TEXT NOT NULL DEFAULT '', valid_until TEXT NOT NULL DEFAULT '', relation_id BIGINT, subject_kind BIGINT, object_kind BIGINT);
CREATE TABLE IF NOT EXISTS memories (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  tier TEXT NOT NULL DEFAULT 'L0',  kind TEXT NOT NULL DEFAULT 'fact',  key TEXT NOT NULL,  content TEXT NOT NULL DEFAULT '',  use_cases TEXT NOT NULL DEFAULT '',  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0,  use_count BIGINT NOT NULL DEFAULT 0,  last_used_at TEXT,  source_session TEXT,  valid_from TEXT,  valid_until TEXT,  artifact_type TEXT,  artifact_ref TEXT,  artifact_hash TEXT,  effectiveness DOUBLE PRECISION DEFAULT NULL,  sensitivity TEXT NOT NULL DEFAULT 'normal',  evidence_strength DOUBLE PRECISION NOT NULL DEFAULT 0.5,  observation_count BIGINT NOT NULL DEFAULT 1,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')), salience DOUBLE PRECISION NOT NULL DEFAULT 0.5, surprise DOUBLE PRECISION NOT NULL DEFAULT 0.5, contradiction_group TEXT NOT NULL DEFAULT '', merged_into BIGINT NOT NULL DEFAULT 0, negation_tokens TEXT NOT NULL DEFAULT '', lifecycle_state TEXT NOT NULL DEFAULT 'active', archive_reason TEXT NOT NULL DEFAULT '', ttl_at TEXT NOT NULL DEFAULT '', cognified_memory_kind TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS memory_provenance (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL,  action TEXT NOT NULL,  details TEXT,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_conflicts (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_a BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  memory_b BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  detected_at TEXT NOT NULL,  resolved BIGINT NOT NULL DEFAULT 0,  resolution TEXT);
CREATE TABLE IF NOT EXISTS tasks (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  parent_id BIGINT DEFAULT 0,  title TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'todo',  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0,  session_id TEXT,  success_criteria TEXT DEFAULT '',  description TEXT DEFAULT '',  acceptance_json TEXT DEFAULT '',  assignee TEXT DEFAULT '',  estimate_minutes BIGINT DEFAULT 0,  created_at TEXT NOT NULL,  updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS task_edges (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  source_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  target_id BIGINT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'depends_on');
CREATE TABLE IF NOT EXISTS decision_log (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  task_id BIGINT DEFAULT 0,  options TEXT NOT NULL,  chosen TEXT NOT NULL,  rationale TEXT NOT NULL DEFAULT '',  assumptions TEXT NOT NULL DEFAULT '',  outcome TEXT,  created_at TEXT NOT NULL);
-- kb_audit_event: the aimee-kb per-service WORM audit store (S5). Append-only,
-- hash-chained (identical record + canonicalization to the aimee-server SQLite
-- store, via audit_worm_chain). WORM is enforced by (a) BEFORE UPDATE/DELETE/
-- TRUNCATE triggers here + (b) a writer role granted only INSERT/SELECT at
-- provisioning (validated: REVOKE UPDATE/DELETE blocks mutation).
CREATE TABLE IF NOT EXISTS kb_audit_event (  seq BIGINT PRIMARY KEY,  ts TEXT NOT NULL,  actor_role TEXT NOT NULL DEFAULT '',  actor_principal TEXT NOT NULL DEFAULT '',  action TEXT NOT NULL,  subject TEXT NOT NULL DEFAULT '',  verdict TEXT NOT NULL DEFAULT '',  detail TEXT NOT NULL DEFAULT '',  key_id TEXT NOT NULL DEFAULT '',  prev_hash TEXT NOT NULL,  row_hash TEXT NOT NULL);
CREATE OR REPLACE FUNCTION kb_worm_block() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'WORM: kb_audit_event is append-only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS kb_audit_no_update ON kb_audit_event;
CREATE TRIGGER kb_audit_no_update BEFORE UPDATE ON kb_audit_event FOR EACH ROW EXECUTE FUNCTION kb_worm_block();
DROP TRIGGER IF EXISTS kb_audit_no_delete ON kb_audit_event;
CREATE TRIGGER kb_audit_no_delete BEFORE DELETE ON kb_audit_event FOR EACH ROW EXECUTE FUNCTION kb_worm_block();
DROP TRIGGER IF EXISTS kb_audit_no_truncate ON kb_audit_event;
CREATE TRIGGER kb_audit_no_truncate BEFORE TRUNCATE ON kb_audit_event FOR EACH STATEMENT EXECUTE FUNCTION kb_worm_block();
CREATE TABLE IF NOT EXISTS anti_patterns (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  hit_count BIGINT NOT NULL DEFAULT 0,  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0);
-- kb_enrollments: queryable record of redeemed client certificates (the accounts
-- surface for the aimee-kb web console). One row per issued cert, keyed by the
-- sha256 fingerprint of the cert DER; revoked_at is the revocation source of
-- truth (checked at the mTLS seam). Migration is idempotent; legacy certs issued
-- before this table are backfilled on first authenticated request.
CREATE TABLE IF NOT EXISTS kb_enrollments (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  scope TEXT NOT NULL DEFAULT '',  fingerprint TEXT NOT NULL,  serial TEXT NOT NULL DEFAULT '',  state TEXT NOT NULL DEFAULT 'active',  issued_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  last_seen_at TEXT NOT NULL DEFAULT '',  expires_at TEXT NOT NULL DEFAULT '',  revoked_at TEXT NOT NULL DEFAULT '',  legacy BIGINT NOT NULL DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS idx_kbenroll_fp ON kb_enrollments(fingerprint);
CREATE INDEX IF NOT EXISTS idx_kbenroll_scope ON kb_enrollments(scope);
-- kb_console_oidc: the single-row (id=1) OIDC login config the web console reads
-- to verify browser identity tokens. Editable via the console's /v1/config/oidc;
-- the console fetches it at startup (restart to re-apply).
CREATE TABLE IF NOT EXISTS kb_console_oidc (  id BIGINT PRIMARY KEY,  issuer TEXT NOT NULL DEFAULT '',  audience TEXT NOT NULL DEFAULT '',  jwks_url TEXT NOT NULL DEFAULT '',  admin_claim TEXT NOT NULL DEFAULT '',  admin_values TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT '');
-- workflow_patterns: durable store for promoted `workflow` learning candidates
-- (the cross-source-learning-pipeline promotion target surface). Written by
-- learning_promote; read by future workflow-suggestion consumers.
CREATE TABLE IF NOT EXISTS workflow_patterns (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  pattern TEXT NOT NULL,  description TEXT NOT NULL DEFAULT '',  source TEXT NOT NULL DEFAULT '',  source_ref TEXT NOT NULL DEFAULT '',  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS tool_registry (  name TEXT PRIMARY KEY,  description TEXT NOT NULL,  input_schema TEXT NOT NULL,  output_schema TEXT DEFAULT '',  side_effect TEXT NOT NULL DEFAULT 'read',  idempotent BIGINT NOT NULL DEFAULT 0,  enabled BIGINT NOT NULL DEFAULT 1,  tool_prompt TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS memory_health (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  cycle_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  total_memories BIGINT NOT NULL DEFAULT 0,  contradictions_detected BIGINT NOT NULL DEFAULT 0,  promotions BIGINT NOT NULL DEFAULT 0,  demotions BIGINT NOT NULL DEFAULT 0,  expirations BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS contradiction_log (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  detected_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  memory_a_id BIGINT REFERENCES memories(id) ON DELETE CASCADE,  memory_b_id BIGINT REFERENCES memories(id) ON DELETE CASCADE,  resolution TEXT NOT NULL DEFAULT 'pending',  details TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_workspaces (  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  workspace TEXT NOT NULL,  PRIMARY KEY(memory_id, workspace));
CREATE TABLE IF NOT EXISTS kind_lifecycle (  kind TEXT PRIMARY KEY,  promote_use_count BIGINT NOT NULL,  promote_confidence DOUBLE PRECISION NOT NULL,  demote_days BIGINT NOT NULL,  demote_confidence DOUBLE PRECISION NOT NULL,  expire_days BIGINT NOT NULL,  demotion_resistance DOUBLE PRECISION NOT NULL);
-- Keep agent_outcomes aligned with what agent_runtime.c:record_outcome writes.
-- Drop and recreate because older greenfield snapshots had a mismatched shape.
DROP TABLE IF EXISTS agent_outcomes;
CREATE TABLE IF NOT EXISTS agent_outcomes (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  agent_name TEXT NOT NULL DEFAULT '',  role TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL,  reason TEXT DEFAULT '',  turns_used BIGINT NOT NULL DEFAULT 0,  tools_called BIGINT NOT NULL DEFAULT 0,  tokens_used BIGINT NOT NULL DEFAULT 0,  tool_error_pattern TEXT DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_links (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  source_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  relation TEXT NOT NULL DEFAULT 'related',  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS trace_mining_log (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  last_trace_id BIGINT NOT NULL DEFAULT 0,  mined_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS mining_jobs (  id TEXT PRIMARY KEY,  last_run_at TEXT,  hwm BIGINT NOT NULL DEFAULT 0,  interval_s INTEGER NOT NULL DEFAULT 300,  enabled BOOLEAN NOT NULL DEFAULT TRUE,  last_error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS interaction_event_embeddings (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  source_event_id BIGINT NOT NULL UNIQUE,  session_id TEXT NOT NULL DEFAULT '',  event_type TEXT NOT NULL,  role TEXT NOT NULL DEFAULT '',  failure_mode TEXT NOT NULL DEFAULT '',  payload_json JSONB NOT NULL DEFAULT '{}',  embedding TEXT NOT NULL DEFAULT '[]',  cluster_key TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (pg_now_text()));
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_type_id ON interaction_event_embeddings (event_type, source_event_id);
CREATE INDEX IF NOT EXISTS idx_interaction_event_embeddings_failure ON interaction_event_embeddings (role, failure_mode);
CREATE TABLE IF NOT EXISTS code_calls (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  file_id BIGINT NOT NULL REFERENCES files(id) ON DELETE CASCADE,  caller TEXT NOT NULL DEFAULT '',  callee TEXT NOT NULL DEFAULT '',  line BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS file_contents (  file_id BIGINT PRIMARY KEY REFERENCES files(id) ON DELETE CASCADE,  content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kb_runtime_state (  state_key TEXT PRIMARY KEY,  state_value TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS notes (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  title TEXT NOT NULL,  slug TEXT NOT NULL UNIQUE,  content TEXT NOT NULL,  tags TEXT NOT NULL DEFAULT '',  author TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS agent_hints (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  role TEXT NOT NULL,  pattern TEXT NOT NULL,  hint TEXT NOT NULL,  consumed BIGINT NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS collab_rules (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  text TEXT NOT NULL,  reason TEXT NOT NULL DEFAULT '',  proposed_by TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'proposed',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  decided_at TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS collab_rules_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
-- kb_meta: durable KB-level key/value facts. Holds schema_embedding_dim — the
-- embedding dimension the halfvec columns were actually sized at — so a later
-- config/embedder change that disagrees is REFUSED at schema apply rather than
-- silently sizing the schema against a mismatched embedder (the dim-drift that
-- silently breaks vector search; embedder-runtime-fetch-autodim §2).
CREATE TABLE IF NOT EXISTS kb_meta (  key TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '');
-- kb_documents: canonical chunk rows. Embedding bytes are NOT stored here.
-- Vectors live in the pgvector extension tables (joined by document id).
-- chunk_strategy records which chunking policy produced this row.
-- chunk_context is a derived retrieval-aid field; it does not replace content.
CREATE TABLE IF NOT EXISTS kb_documents (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  project TEXT NOT NULL,  file_path TEXT NOT NULL,  file_hash TEXT NOT NULL,  chunk_index BIGINT NOT NULL,  heading_path TEXT NOT NULL DEFAULT '',  line_start BIGINT NOT NULL DEFAULT 0,  line_end BIGINT NOT NULL DEFAULT 0,  content TEXT NOT NULL,  token_count BIGINT NOT NULL DEFAULT 0,  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')), prev_chunk_id BIGINT DEFAULT NULL, next_chunk_id BIGINT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS kb_async_jobs (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  kind TEXT NOT NULL DEFAULT 'embed_raw',  document_id BIGINT NOT NULL REFERENCES kb_documents(id) ON DELETE CASCADE,  project TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts BIGINT NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  claimed_by TEXT NOT NULL DEFAULT '',  claimed_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  next_attempt_at TEXT NOT NULL DEFAULT '',  UNIQUE(kind, document_id));
-- Retry backoff: pre-existing DBs predate next_attempt_at, and CREATE TABLE IF NOT
-- EXISTS is a no-op for them, so the column is added here for upgrades. Must stay
-- AFTER the CREATE above -- ordered before it, this ALTER aborts schema apply on a
-- fresh database with "relation kb_async_jobs does not exist".
ALTER TABLE kb_async_jobs ADD COLUMN IF NOT EXISTS next_attempt_at TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS memory_aliases (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  alias TEXT NOT NULL,  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  UNIQUE(memory_id, alias));
CREATE TABLE IF NOT EXISTS memory_entities (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  entity TEXT NOT NULL,  role TEXT NOT NULL DEFAULT 'mention',  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  UNIQUE(memory_id, entity, role));
CREATE TABLE IF NOT EXISTS memory_temporal_refs (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  ref_key TEXT NOT NULL,  granularity TEXT NOT NULL DEFAULT 'relative',  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  UNIQUE(memory_id, ref_key, granularity));
CREATE TABLE IF NOT EXISTS memory_event_frames (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  actor TEXT NOT NULL DEFAULT '',  action TEXT NOT NULL DEFAULT '',  object TEXT NOT NULL DEFAULT '',  location TEXT NOT NULL DEFAULT '',  event_time TEXT NOT NULL DEFAULT '',  evidence_kind TEXT NOT NULL DEFAULT 'derived',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_summaries (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope TEXT NOT NULL DEFAULT 'headline',  summary TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  UNIQUE(memory_id, scope));
CREATE TABLE IF NOT EXISTS retrieval_shortcuts (  normalized_query TEXT PRIMARY KEY,  target_ids TEXT NOT NULL DEFAULT '',  hit_count BIGINT NOT NULL DEFAULT 0,  promoted BIGINT NOT NULL DEFAULT 0,  last_used_at TEXT NOT NULL DEFAULT (pg_now_text()),  updated_at TEXT NOT NULL DEFAULT (pg_now_text()));
CREATE TABLE IF NOT EXISTS memory_chunks (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  chunk_index BIGINT NOT NULL DEFAULT 0,  chunk_text TEXT NOT NULL,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  UNIQUE(memory_id, chunk_index));
CREATE TABLE IF NOT EXISTS memory_units (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  unit_type TEXT NOT NULL,  unit_key TEXT NOT NULL DEFAULT '',  unit_text TEXT NOT NULL,  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')), memory_kind TEXT NOT NULL DEFAULT 'episodic', is_episode_card BIGINT NOT NULL DEFAULT 0,  UNIQUE(memory_id, unit_type, unit_key, unit_text));
CREATE TABLE IF NOT EXISTS memory_unit_edges (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  src_unit_id BIGINT NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  dst_unit_id BIGINT NOT NULL REFERENCES memory_units(id) ON DELETE CASCADE,  edge_type TEXT NOT NULL DEFAULT 'related',  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_episodes (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_key TEXT NOT NULL,  episode_text TEXT NOT NULL,  source_session TEXT NOT NULL DEFAULT '',  reference_time TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_relations (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  episode_id BIGINT DEFAULT 0,  src_entity TEXT NOT NULL DEFAULT '',  relation TEXT NOT NULL DEFAULT '',  dst_entity TEXT NOT NULL DEFAULT '',  fact_text TEXT NOT NULL DEFAULT '',  valid_at TEXT NOT NULL DEFAULT '',  invalid_at TEXT NOT NULL DEFAULT '',  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_scopes (  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  scope_type TEXT NOT NULL,  scope_value TEXT NOT NULL,  PRIMARY KEY(memory_id, scope_type, scope_value));
CREATE TABLE IF NOT EXISTS entity_profiles (  entity_id TEXT NOT NULL PRIMARY KEY,  canonical_name TEXT NOT NULL,  observation_count BIGINT NOT NULL DEFAULT 0,  card_json TEXT NOT NULL DEFAULT '{}',  last_refreshed TEXT NOT NULL,  created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memory_lineage (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  object_type TEXT NOT NULL,  object_id BIGINT NOT NULL,  source_kind TEXT NOT NULL,  source_ref TEXT NOT NULL DEFAULT '',  ingested_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0);
CREATE TABLE IF NOT EXISTS memory_scenes (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  workspace_id TEXT NOT NULL DEFAULT '',  turn_count BIGINT NOT NULL DEFAULT 0,  noise_ratio DOUBLE PRECISION NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_scene_members (  scene_id BIGINT NOT NULL REFERENCES memory_scenes(id) ON DELETE CASCADE,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  membership_strength DOUBLE PRECISION NOT NULL DEFAULT 1.0,  PRIMARY KEY(scene_id, memory_id));
CREATE TABLE IF NOT EXISTS memory_relation_schema (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  relation_id BIGINT NOT NULL,  subject_kind BIGINT NOT NULL DEFAULT 99,  object_kind  BIGINT NOT NULL DEFAULT 99);
CREATE TABLE IF NOT EXISTS memory_active_embedder (  id         BIGINT PRIMARY KEY CHECK (id = 1),  version    TEXT NOT NULL DEFAULT '',  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_reembed_progress (  id             BIGINT PRIMARY KEY CHECK (id = 1),  target_version TEXT    NOT NULL DEFAULT '',  last_id        BIGINT NOT NULL DEFAULT 0,  total          BIGINT NOT NULL DEFAULT 0,  done           BIGINT NOT NULL DEFAULT 0,  started_at     TEXT    NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  finished_at    TEXT    DEFAULT NULL);
CREATE TABLE IF NOT EXISTS memory_coref_audit (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  memory_id BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  session_id TEXT NOT NULL DEFAULT '',  outcome TEXT NOT NULL DEFAULT 'none',  entity TEXT NOT NULL DEFAULT '',  mode TEXT NOT NULL DEFAULT '',  confidence DOUBLE PRECISION NOT NULL DEFAULT 0.0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS curator_invalidation_events (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  source_kind TEXT NOT NULL DEFAULT '',  source_id TEXT NOT NULL DEFAULT '',  artifacts_stale INTEGER NOT NULL DEFAULT 0,  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS code_index_ops (  point_id BIGINT PRIMARY KEY,  project TEXT NOT NULL DEFAULT '',  node_key TEXT NOT NULL DEFAULT '',  file_path TEXT NOT NULL DEFAULT '',  status TEXT NOT NULL DEFAULT 'pending',  attempts BIGINT NOT NULL DEFAULT 0,  last_error TEXT NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS vector_index_ops (  point_id   BIGINT PRIMARY KEY,  collection TEXT    NOT NULL DEFAULT 'memory_units',  memory_id  BIGINT REFERENCES memories(id) ON DELETE CASCADE,  status     TEXT    NOT NULL DEFAULT 'pending',  attempts   BIGINT NOT NULL DEFAULT 0,  last_error TEXT    NOT NULL DEFAULT '',  indexed_at TEXT,  updated_at TEXT    NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS memory_promotion_approvals (  memory_id    BIGINT NOT NULL REFERENCES memories(id) ON DELETE CASCADE,  target_tier  TEXT    NOT NULL,  approver     TEXT    NOT NULL DEFAULT 'operator',  note         TEXT    NOT NULL DEFAULT '',  approved_at  TEXT    NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  PRIMARY KEY (memory_id, target_tier));
CREATE TABLE IF NOT EXISTS prospective_memories (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  trigger_text TEXT NOT NULL,  action_text TEXT NOT NULL,  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  recurrence TEXT NOT NULL DEFAULT 'once',  state TEXT NOT NULL DEFAULT 'armed',  valid_until TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  trigger_count BIGINT NOT NULL DEFAULT 0,  last_triggered_at TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS epistemic_directives (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  question TEXT NOT NULL,  topic TEXT NOT NULL DEFAULT '',  anchor_entity TEXT NOT NULL DEFAULT '',  anchor_file TEXT NOT NULL DEFAULT '',  cause TEXT NOT NULL,  priority BIGINT NOT NULL DEFAULT 50,  state TEXT NOT NULL DEFAULT 'open',  memory_a_id BIGINT NOT NULL DEFAULT 0,  memory_b_id BIGINT NOT NULL DEFAULT 0,  resolution_memory_id BIGINT NOT NULL DEFAULT 0,  evidence TEXT NOT NULL DEFAULT '',  source_session TEXT NOT NULL DEFAULT '',  surfaced_count BIGINT NOT NULL DEFAULT 0,  last_surfaced_at TEXT NOT NULL DEFAULT '',  resolved_at TEXT NOT NULL DEFAULT '',  valid_until TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS failed_queries (  query_norm TEXT PRIMARY KEY,  failure_count BIGINT NOT NULL DEFAULT 0,  last_failed_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS working_profile_state (  field TEXT PRIMARY KEY,  value TEXT NOT NULL DEFAULT '',  sample_count BIGINT NOT NULL DEFAULT 0,  confidence DOUBLE PRECISION NOT NULL DEFAULT 0.0,  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS working_profile_observations (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  field TEXT NOT NULL,  value TEXT NOT NULL,  confidence DOUBLE PRECISION NOT NULL DEFAULT 0.5,  source_session TEXT NOT NULL DEFAULT '',  observed_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS curiosity_items (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  gap_type TEXT NOT NULL,  target_entity TEXT NOT NULL DEFAULT '',  target_topic TEXT NOT NULL DEFAULT '',  evidence TEXT NOT NULL DEFAULT '',  importance DOUBLE PRECISION NOT NULL DEFAULT 0.0,  novelty DOUBLE PRECISION NOT NULL DEFAULT 0.0,  progress DOUBLE PRECISION NOT NULL DEFAULT 0.0,  routing_score DOUBLE PRECISION NOT NULL DEFAULT 0.0,  state TEXT NOT NULL DEFAULT 'open',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS learning_signals (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  signal_type TEXT NOT NULL,  source TEXT NOT NULL DEFAULT 'explicit',  polarity TEXT NOT NULL DEFAULT '',  title TEXT NOT NULL DEFAULT '',  description TEXT NOT NULL DEFAULT '',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id BIGINT NOT NULL DEFAULT 0,  correction_text TEXT NOT NULL DEFAULT '',  workflow_project TEXT NOT NULL DEFAULT '',  workflow_signal_type TEXT NOT NULL DEFAULT '',  evidence_refs TEXT NOT NULL DEFAULT '[]',  source_session TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
CREATE TABLE IF NOT EXISTS learning_proposals (  id BIGINT PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,  signal_id BIGINT NOT NULL REFERENCES learning_signals(id) ON DELETE CASCADE,  sink TEXT NOT NULL,  state TEXT NOT NULL DEFAULT 'pending',  target_key TEXT NOT NULL DEFAULT '',  target_memory_id BIGINT NOT NULL DEFAULT 0,  action_json TEXT NOT NULL DEFAULT '{}',  evidence_refs TEXT NOT NULL DEFAULT '[]',  corroboration_count BIGINT NOT NULL DEFAULT 1,  expires_at TEXT NOT NULL DEFAULT '',  committed_at TEXT NOT NULL DEFAULT '',  archive_reason TEXT NOT NULL DEFAULT '',  created_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')),  updated_at TEXT NOT NULL DEFAULT (to_char(CURRENT_TIMESTAMP, 'YYYY-MM-DD HH24:MI:SS')));
